root=pathlib.Path.cwd()
with tempfile.TemporaryDirectory(prefix="b07-independent-") as tmp:
    base=pathlib.Path(tmp)
    for module in ("pose-mcp","mcp-enforce"):
        shutil.copytree(root/module,base/module,ignore=shutil.ignore_patterns(".git","node_modules","*.test"))
    for path,body in SOURCES.items():
        (base/"pose-mcp"/path).write_text(body)
    result=subprocess.run(["go","test","./internal/pose","./internal/cli","-run","^TestB07Independent","-count=1","-v"],cwd=base/"pose-mcp")
